#!/usr/bin/env python3

"""
Test different approaches to fix the issue.
"""

from dataclasses import dataclass
from mashumaro.jsonschema import build_json_schema
from mashumaro.jsonschema.models import JSONSchema
import json
import jsonschema


@dataclass
class InnerData:
    name: str
    value: int


@dataclass  
class WritableManifest:
    """Top-level object similar to the one mentioned in the issue."""
    id: str
    items: list[InnerData]
    version: int = 1


def approach1_current_behavior():
    """Current behavior - problematic for validation."""
    print("=== Approach 1: Current Behavior ===")
    schema = build_json_schema(WritableManifest, all_refs=True)
    schema_dict = schema.to_dict()
    print("Generated schema:")
    print(json.dumps(schema_dict, indent=2))

    # Test data
    test_data = {
        "id": "test-manifest",
        "items": [
            {"name": "item1", "value": 100},
            {"name": "item2", "value": 200}
        ],
        "version": 1
    }

    try:
        jsonschema.validate(test_data, schema_dict)
        print("Validation: SUCCESS")
    except Exception as e:
        print(f"Validation: FAILED - {e}")


def approach2_separate_reference_and_definitions():
    """Approach 2: Separate reference from definitions."""
    print("\n=== Approach 2: Separate Reference and Definitions ===")
    # Get the reference schema
    ref_schema = build_json_schema(WritableManifest, all_refs=True)

    # Extract just the reference part
    reference_only = JSONSchema(reference=ref_schema.reference)
    reference_dict = reference_only.to_dict()
    print("Reference-only schema:")  
    print(json.dumps(reference_dict, indent=2))

    # Extract the definitions
    definitions_only = ref_schema.definitions
    if definitions_only:
        # Create a schema that contains just the definitions
        container_schema = JSONSchema(definitions=definitions_only)
        definitions_dict = container_schema.to_dict()
        print("Definitions container:")
        print(json.dumps(definitions_dict, indent=2))

        # For validation, we'd need to merge them properly
        # But this shows the structure issue


def approach3_top_level_full_schema():
    """Approach 3: Top-level remains full schema, nested use refs."""
    print("\n=== Approach 3: Top-level Full Schema ===")

    # This would require modifying the on_dataclass function
    # to not convert top-level objects to references
    # Let's simulate what it should look like:

    full_schema_dict = {
        "type": "object",
        "title": "WritableManifest",
        "properties": {
            "id": {"type": "string"},
            "items": {
                "type": "array", 
                "items": {"$ref": "#/defs/InnerData"}
            },
            "version": {"type": "integer", "default": 1}
        },
        "additionalProperties": False,
        "required": ["id", "items"],
        "$defs": {
            "InnerData": {
                "type": "object",
                "title": "InnerData", 
                "properties": {
                    "name": {"type": "string"},
                    "value": {"type": "integer"}
                },
                "additionalProperties": False,
                "required": ["name", "value"]
            }
        }
    }

    print("Simulated corrected schema:")
    print(json.dumps(full_schema_dict, indent=2))

    # Test data
    test_data = {
        "id": "test-manifest",
        "items": [
            {"name": "item1", "value": 100},
            {"name": "item2", "value": 200}
        ],
        "version": 1
    }

    try:
        jsonschema.validate(test_data, full_schema_dict)
        print("Validation: SUCCESS")
    except Exception as e:
        print(f"Validation: FAILED - {e}")


if __name__ == "__main__":
    approach1_current_behavior()
    approach2_separate_reference_and_definitions() 
    approach3_top_level_full_schema()

