#!/usr/bin/env python3

"""
Test if fixing the reference resolves the issue.
"""

from dataclasses import dataclass
from mashumaro.jsonschema import build_json_schema
from mashumaro.jsonschema.models import JSONSchema
import json
import jsonschema


@dataclass
class InnerData:
    name: str
    value: int


@dataclass  
class WritableManifest:
    id: str
    items: list[InnerData]
    version: int = 1


def test_fixed_reference():
    """Test with corrected reference."""
    # Get mashumaro output
    schema = build_json_schema(WritableManifest, all_refs=True)
    schema_dict = schema.to_dict()

    print("Original mashumaro output:")
    print(json.dumps(schema_dict, indent=2))

    # Fix the reference from #/defs/ to #/$defs/
    fixed_schema_dict = schema_dict.copy()
    if '$ref' in fixed_schema_dict and fixed_schema_dict['$ref'].startswith('#/defs/'):
        fixed_schema_dict['$ref'] = fixed_schema_dict['$ref'].replace('#/defs/', '#/$defs/')

    # Also fix internal references  
    if '$defs' in fixed_schema_dict:
        for def_key, def_value in fixed_schema_dict['$defs'].items():
            # Fix references in definitions recursively
            def_value_str = json.dumps(def_value)
            if '#/defs/' in def_value_str:
                fixed_def_str = def_value_str.replace('#/defs/', '#/$defs/')
                fixed_schema_dict['$defs'][def_key] = json.loads(fixed_def_str)

    print("\nFixed output:")
    print(json.dumps(fixed_schema_dict, indent=2))

    # Test data
    test_data = {
        "id": "test-manifest",
        "items": [
            {"name": "item1", "value": 100},
            {"name": "item2", "value": 200}
        ],
        "version": 1
    }

    try:
        jsonschema.validate(test_data, fixed_schema_dict)
        print("Validation: SUCCESS")
        return True
    except Exception as e:
        print(f"Validation: FAILED - {e}")
        return False


if __name__ == "__main__":
    success = test_fixed_reference()
    if success:
        print("\n✓ Issue is in the reference URL construction!")
    else:
        print("\n✗ Issue is something else.")

