#!/usr/bin/env python3

"""
Test edge cases to ensure the fix is robust.
"""

from dataclasses import dataclass
from typing import List, Optional
from mashumaro.jsonschema import build_json_schema
import json
import jsonschema


@dataclass
class SimpleClass:
    name: str


@dataclass  
class NestedClass:
    simple: SimpleClass
    items: List[SimpleClass]


@dataclass
class DeepNestedClass:
    nested: NestedClass
    optional_simple: Optional[SimpleClass] = None


def test_simple_case():
    """Test simple case."""
    print("=== Simple Case ===")
    schema = build_json_schema(SimpleClass, all_refs=True)
    schema_dict = schema.to_dict()
    print(json.dumps(schema_dict, indent=2))

    test_data = {"name": "test"}
    try:
        jsonschema.validate(test_data, schema_dict)
        print("✓ Validation successful")
    except Exception as e:
        print(f"✗ Validation failed: {e}")


def test_nested_case():
    """Test nested case.""" 
    print("\n=== Nested Case ===")
    schema = build_json_schema(NestedClass, all_refs=True)
    schema_dict = schema.to_dict()
    print(json.dumps(schema_dict, indent=2))

    test_data = {
        "simple": {"name": "simple1"},
        "items": [
            {"name": "item1"},
            {"name": "item2"}
        ]
    }
    try:
        jsonschema.validate(test_data, schema_dict)
        print("✓ Validation successful")
    except Exception as e:
        print(f"✗ Validation failed: {e}")


def test_deep_nested_case():
    """Test deep nested case."""
    print("\n=== Deep Nested Case ===")
    schema = build_json_schema(DeepNestedClass, all_refs=True)
    schema_dict = schema.to_dict()
    print(json.dumps(schema_dict, indent=2))

    test_data = {
        "nested": {
            "simple": {"name": "simple1"},
            "items": [{"name": "item1"}]
        },
        "optional_simple": {"name": "optional"}
    }
    try:
        jsonschema.validate(test_data, schema_dict)
        print("✓ Validation successful")
    except Exception as e:
        print(f"✗ Validation failed: {e}")

    # Test without optional field
    test_data2 = {
        "nested": {
            "simple": {"name": "simple1"},
            "items": [{"name": "item1"}]
        }
    }
    try:
        jsonschema.validate(test_data2, schema_dict)
        print("✓ Validation successful (without optional)")
    except Exception as e:
        print(f"✗ Validation failed (without optional): {e}")


def test_openapi_dialect():
    """Test that OpenAPI dialect still works correctly."""
    print("\n=== OpenAPI Dialect ===")
    from mashumaro.jsonschema.dialects import OPEN_API_3_1

    schema = build_json_schema(SimpleClass, all_refs=True, dialect=OPEN_API_3_1)
    schema_dict = schema.to_dict()
    print(json.dumps(schema_dict, indent=2))

    # Should use OpenAPI style references
    if '$ref' in schema_dict:
        ref = schema_dict['$ref']
        print(f"Reference: {ref}")
        if ref.startswith('#/components/schemas/'):
            print("✓ Correct OpenAPI reference format")
        else:
            print("✗ Incorrect reference format for OpenAPI")


if __name__ == "__main__":
    test_simple_case()
    test_nested_case()
    test_deep_nested_case()
    test_openapi_dialect()

